def build():
    out = []
    ids = set()
    for (pid, zh, orig, pos, hist, by, src, conf, note) in C:
        assert pid not in ids, pid
        ids.add(pid)
        if isinstance(orig, str) and orig.startswith('@'):
            orig = zh
        h = [[f'1941-{t}', who] for t, who in hist]
        for a, b in zip(h, h[1:]):
            assert a[0] < b[0], (pid, h)
        e = {'id': pid, 'zh': zh, 'orig': orig, 'pos': pos, 'hist': h, 'by': by,
             'sources': [S[s] for s in src.split()], 'confidence': conf}
        if note:
            e['note'] = note
        out.append(e)
    p = os.path.join(HERE, 'captures.json')
    with open(p, 'w', encoding='utf-8') as f:
        f.write('[\n' + ',\n'.join(' ' + json.dumps(e, ensure_ascii=False) for e in out) + '\n]\n')
    print(f'captures.json：{len(out)} 个地点 → {p}')


if __name__ == '__main__':
    build()
